const USERS = [
  { tenant: 'acme', id: 7, display_name: 'Dana Whitfield' },
  { tenant: 'acme', id: 8, display_name: 'Omar Haddad' },
  { tenant: 'globex', id: 7, display_name: 'Priya Raman' },
  { tenant: 'globex', id: 9, display_name: 'Lee Chen' },
];

async function findUser(tenantId, userId) {
  return USERS.find((u) => u.tenant === tenantId && u.id === userId) || null;
}

module.exports = { findUser };

