'use strict';

const TTL_MS = 60000;
const store = new Map();

function makeKey(tenantId, userId) {
  return `${tenantId}:${userId}`;
}

function get(tenantId, userId, now = Date.now()) {
  const entry = store.get(makeKey(tenantId, userId));
  if (!entry || entry.expires <= now) return undefined;
  return entry.value;
}

function set(tenantId, userId, value, now = Date.now()) {
  store.set(makeKey(tenantId, userId), { value, expires: now + TTL_MS });
}

function clear() {
  store.clear();
}

module.exports = { get, set, clear, makeKey };

