const cache = require('./cache');
const db = require('./db');

async function getProfile(tenantId, userId) {
  const cached = cache.get(tenantId, userId);
  if (cached) return cached;
  const row = await db.findUser(tenantId, userId);
  if (!row) return null;
  const profile = { id: row.id, name: row.display_name, tenant: tenantId };
  cache.set(tenantId, userId, profile);
  return profile;
}

module.exports = { getProfile };

