const test = require('node:test');
const assert = require('node:assert');
const cache = require('../src/cache');
const { getProfile } = require('../src/userService');

test('returns the profile for a known user', async () => {
  cache.clear();
  const profile = await getProfile('acme', 7);
  assert.strictEqual(profile.name, 'Dana Whitfield');
});

test('returns null for an unknown user', async () => {
  cache.clear();
  assert.strictEqual(await getProfile('acme', 99), null);
});

